class Solution {
public:
    vector<int> nextLargerNodes(ListNode* head) {
        vector<int> vals, res;
        stack<int> st;
        int i = 0;
        for (ListNode* cur = head; cur; cur = cur->next, i++) {
            vals.push_back(cur->val);
            res.push_back(0);
            while (!st.empty() && vals[st.top()] < cur->val) {
                res[st.top()] = cur->val;
                st.pop();
            }
            st.push(i);
        }
        return res;
    }
};
